syntax:
template<class InputIt, class ForwardIt>
InputIt find_first_of(InputIt first1, InputIt last1, ForwardIt first2, ForwardIt last2);
// Implementation notes: 
// - InputIt must satisfy InputIterator requirements (e.g., supports *it and ++it for single-pass reading).
// - ForwardIt must satisfy ForwardIterator requirements (e.g., supports multiple ++it operations).
// - The function returns the first iterator it in [first1, last1) where *it equals any element in [first2, last2), or last1 if none found.
// - Overloads exist with predicates: e.g., template<class InputIt, class ForwardIt, class BinaryPredicate> InputIt find_first_of(InputIt first1, InputIt last1, ForwardIt first2, ForwardIt last2, BinaryPredicate p);

code_example:
#include <algorithm>
#include <vector>
#include <iostream>

int main() {
    std::vector<int> vec1 = {1, 2, 3, 4, 5};  // Input range
    std::vector<int> vec2 = {2, 4, 6};       // Search range

    auto it = std::find_first_of(vec1.begin(), vec1.end(), vec2.begin(), vec2.end());

    if (it != vec1.end()) {
        std::cout << "First matching element at index: " << std::distance(vec1.begin(), it) << std::endl;  // Outputs: 1 (for element 2)
    } else {
        std::cout << "No match found" << std::endl;
    }
    return 0;
}
